def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    my = [h[0] for h in history]
    opp = [h[1] for h in history]
    my_defs = 0
    opp_defs = 0
    for x in my:
        if x == 'D':
            my_defs += 1
    for x in opp:
        if x == 'D':
            opp_defs += 1
    if n < 5:
        return 'C'
    if my_defs == 0:
        if n == 5:
            return 'D'
        return 'C'
    first_def = -1
    for i, x in enumerate(my):
        if x == 'D':
            first_def = i
            break
    if first_def + 1 >= n:
        return 'C'
    opp_response = opp[first_def + 1]
    if opp_response == 'D':
        if opp_defs * 2 > n:
            if opp[-1] == 'D':
                if my[-1] == 'D':
                    if rng.random() < 0.3:
                        return 'C'
                    return 'D'
                return 'D'
            if rng.random() < 0.3:
                return 'D'
            return 'C'
        else:
            if n >= 2 and opp[-1] == 'D' and opp[-2] == 'D':
                return 'D'
            if my[-1] == 'D' and opp[-1] == 'D':
                if rng.random() < 0.5:
                    return 'C'
            return 'C'
    else:
        opp_defs_after = 0
        for i in range(first_def + 1, n):
            if opp[i] == 'D':
                opp_defs_after += 1
        if opp_defs_after == 0:
            if rng.random() < 0.8:
                return 'D'
            return 'C'
        else:
            if opp[-1] == 'D':
                return 'C'
            if rng.random() < 0.4:
                return 'D'
            return 'C'
